record.field:
{
  "type": "object",
  "title": "InviteUserRequest",
  "required": ["profile_id"],
  "properties": {
    "profile_id": {"type": "integer", "example": 17, "description": "ID of an existing thedevkitchen.estate.profile record -- the only field this endpoint accepts, for any profile_type"}
  }
}

{
  "type": "object",
  "title": "InviteUserResponse",
  "required": ["success", "data", "message"],
  "properties": {
    "success": {"type": "boolean", "example": true},
    "data": {
      "type": "object",
      "required": ["id", "name", "email", "document", "profile", "profile_id", "signup_pending", "invite_sent_at", "invite_expires_at"],
      "properties": {
        "id":               {"type": "integer", "example": 42, "description": "res.users ID of the invited user"},
        "name":             {"type": "string",  "example": "João Silva"},
        "email":            {"type": "string",  "example": "joao.silva@example.com"},
        "document":         {"type": "string",  "example": "12345678909", "description": "CPF/CNPJ from the source profile record"},
        "profile":          {"type": "string",  "example": "agent", "description": "profile_type code of the source thedevkitchen.estate.profile record"},
        "profile_id":       {"type": "integer", "example": 17},
        "signup_pending":   {"type": "boolean", "example": true},
        "invite_sent_at":   {"type": ["string", "null"], "format": "date-time", "example": "2025-01-15T10:30:00Z"},
        "invite_expires_at":{"type": ["string", "null"], "format": "date-time", "example": "2025-01-22T10:30:00Z"},
        "email_status":     {"type": "string", "example": "failed", "description": "Only present when the invite email failed to send (value is always 'failed')"},
        "agent_id":         {"type": "integer", "example": 8, "description": "Feature 026: only present when the target profile's type is 'agent' — ID of the real.estate.agent record linked/created during this invite"}
      }
    },
    "message": {"type": "string", "example": "User invited successfully. Email sent to joao.silva@example.com"},
    "links": {
      "type": "object",
      "required": ["self", "resend_invite", "collection", "profile"],
      "properties": {
        "self":          {"type": "string", "example": "/api/v1/users/42"},
        "resend_invite": {"type": "string", "example": "/api/v1/users/42/resend-invite"},
        "collection":    {"type": "string", "example": "/api/v1/users"},
        "profile":       {"type": "string", "example": "/api/v1/profiles/17"},
        "agent":         {"type": "string", "example": "/api/v1/agents/8", "description": "Feature 026: only present when the target profile's type is 'agent'"}
      }
    }
  }
}

{
  "type": "object",
  "title": "ForgotPasswordResponse",
  "properties": {
    "success": {"type": "boolean", "example": true},
    "message": {"type": "string",  "example": "Se este e-mail estiver cadastrado, você receberá as instruções de recuperação."}
  }
}
